#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
    long long lcm(long long a, long long b) {
        return (a / std::gcd(a, b)) * b;
    }
public:
    int minimumIncrements(std::vector<int>& nums, std::vector<int>& target) {
        int m = target.size();
        int max_mask = 1 << m;

        std::vector<long long> subset_lcm(max_mask, 1);
        for (int mask = 1; mask < max_mask; ++mask) {
            long long l = 1;
            for (int i = 0; i < m; ++i) {
                if ((mask >> i) & 1) l = lcm(l, target[i]);
            }
            subset_lcm[mask] = l;
        }

        const long long INF = 1e18;
        std::vector<long long> dp(max_mask, INF);
        dp[0] = 0;

        for (int x : nums) {
            std::vector<long long> next_dp = dp;
            for (int mask = 0; mask < max_mask; ++mask) {
                if (dp[mask] == INF) continue;
                for (int submask = 1; submask < max_mask; ++submask) {
                    long long lcm_val = subset_lcm[submask];
                    long long rem = x % lcm_val;
                    long long cost = (rem == 0) ? 0 : lcm_val - rem;
                    int new_mask = mask | submask;
                    next_dp[new_mask] = std::min(next_dp[new_mask], dp[mask] + cost);
                }
            }
            dp = next_dp;
        }
        return (int)dp[max_mask - 1];
    }
};

import java.util.Arrays;

class Solution {
    private long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    private long lcm(long a, long b) {
        return (a / gcd(a, b)) * b;
    }

    public int minimumIncrements(int[] nums, int[] target) {
        int m = target.length;
        int maxMask = 1 << m;

        long[] subsetLcm = new long[maxMask];
        for (int mask = 1; mask < maxMask; mask++) {
            long l = 1;
            for (int i = 0; i < m; i++) {
                if (((mask >> i) & 1) == 1) l = lcm(l, target[i]);
            }
            subsetLcm[mask] = l;
        }

        long INF = (long)1e18;
        long[] dp = new long[maxMask];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (int x : nums) {
            long[] nextDp = dp.clone();
            for (int mask = 0; mask < maxMask; mask++) {
                if (dp[mask] == INF) continue;
                for (int submask = 1; submask < maxMask; submask++) {
                    long lcmVal = subsetLcm[submask];
                    long rem = x % lcmVal;
                    long cost = (rem == 0) ? 0 : lcmVal - rem;
                    int newMask = mask | submask;
                    nextDp[newMask] = Math.min(nextDp[newMask], dp[mask] + cost);
                }
            }
            dp = nextDp;
        }
        return (int)dp[maxMask - 1];
    }
}

var minimumIncrements = function(nums, target) {
    const m = target.length;
    const maxMask = 1 << m;

    function gcd(a, b) {
        while (b !== 0n) {
            const temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    function lcm(a, b) {
        return (a / gcd(a, b)) * b;
    }

    const subsetLcm = new Array(maxMask).fill(1n);
    for (let mask = 1; mask < maxMask; mask++) {
        let l = 1n;
        for (let i = 0; i < m; i++) {
            if ((mask >> i) & 1) l = lcm(l, BigInt(target[i]));
        }
        subsetLcm[mask] = l;
    }

    const INF = 1e18;
    let dp = new Float64Array(maxMask).fill(INF);
    dp[0] = 0;

    for (const x of nums) {
        const nextDp = new Float64Array(dp);
        const bx = BigInt(x);
        for (let mask = 0; mask < maxMask; mask++) {
            if (dp[mask] === INF) continue;
            for (let submask = 1; submask < maxMask; submask++) {
                const lcmVal = subsetLcm[submask];
                const rem = Number(bx % lcmVal);
                const cost = (rem === 0) ? 0 : Number(lcmVal) - rem;
                const newMask = mask | submask;
                if (dp[mask] + cost < nextDp[newMask]) {
                    nextDp[newMask] = dp[mask] + cost;
                }
            }
        }
        dp = nextDp;
    }
    return dp[maxMask - 1];
};
